const assert = require('node:assert/strict');
const {context, render} = require('./menu-harness.cjs');
const desktop = render('snipplets/navigation/navigation.tpl', context());
// Catches missing consolidation: the legacy navigation has a Shop root and no Menu trigger.
assert.match(desktop, /data-eora-menu/);
assert.match(desktop, />\s*Menu\s*</);
assert.match(desktop, /Best Sellers/);
assert.match(desktop, /Personal Shopper/);
for (const label of ['Óculos', 'Bolsas', 'Cintos', 'Favoritos', 'Gifts', 'Cuidados', 'Conserto', 'Política de troca', 'Lançamentos', 'Pré-venda', 'De volta ao estoque', 'Press']) assert.ok(desktop.includes(label), label);
assert.equal((desktop.match(/data-menu-group=/g) || []).length, 5);
const mobile = render('snipplets/navigation/navigation-panel.tpl', {...context(), primary_links: true});
assert.match(mobile, /data-menu-screen="primary"/);
assert.match(mobile, /data-menu-screen="secondary"/);
assert.match(mobile, /data-menu-screen="shop"/);
const empty = render('snipplets/navigation/navigation.tpl', context({empty: true}));
assert.ok(!empty.includes('<img'), 'empty uploads do not create broken images');
assert.ok(!empty.includes('href="#"'), 'all category links have usable destinations');
const overridden = render('snipplets/navigation/navigation.tpl', context({settings: {eora_menu_bags_url: '/minhas-bolsas/'}}));
assert.match(overridden, /href="\/minhas-bolsas\/"/);
console.log('PASS menu: hierarchy, destinations, empty uploads, custom URLs.');
const discovery = (() => { try { return render('snipplets/header/search-discovery.tpl', context()); } catch { return ''; } })();
assert.equal((discovery.match(/data-search-product/g) || []).length, 6, 'discovery uses six selected products, not the entire catalog');
assert.ok(discovery.indexOf('Óculos Onyx') < discovery.indexOf('Bolsa Mini Vértice'), 'merchant order is preserved');
assert.ok(!discovery.includes('Sétimo produto'));
assert.equal(render('snipplets/header/search-discovery.tpl', context({products: 0})).trim(), '');
console.log('PASS search discovery: six products, merchant order, empty section.');
const partial = render('snipplets/navigation/eora-menu.tpl', {...context({settings: {eora_menu_shop_images: [{title: 'Sem upload'}, {image: '/fixtures/onyx-lifestyle.webp', title: 'Válida'}]}}), mode: 'mobile'});
assert.ok(!partial.includes('alt="Sem upload"'));
assert.ok(partial.includes('alt="Válida"'));
const fallback = render('snipplets/navigation/navigation.tpl', context({settings: {eora_menu_shop_images: []}}));
assert.match(fallback, /alt="Óculos"/);
